// KakaoTalk OG image: use the admin-colored daily dated artwork generated by GitHub Actions.
// Preserve the existing Supabase-managed promotional image as a fallback.
const BASE = 'https://gaygechqnvehajmsnvfb.supabase.co/storage/v1/object/public/gallery/';

function kstDate(offsetDays = 0): string {
  const now = new Date(Date.now() + offsetDays * 86400000);
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: 'Asia/Seoul', year: 'numeric', month: '2-digit', day: '2-digit',
  }).formatToParts(now);
  const get = (type: string) => parts.find(p => p.type === type)?.value || '';
  return `${get('year')}-${get('month')}-${get('day')}`;
}

export default async (_request: Request, context: any) => {
  const response: Response = await context.next();
  const type = response.headers.get('content-type') || '';
  if (response.status !== 200 || !type.includes('text/html')) return response;
  let html = await response.text();
  let imageUrl = '';

  // Daily JPEG is published directly to Supabase, avoiding Netlify deploys.
  // The share link includes the selected image revision. Preserve that revision
  // in the OG image URL so Kakao does not reuse a preview from an older design.
  // Stable latest.jpg avoids broken previews if a scheduled update runs late.
  const shareUrl = new URL(_request.url);
  const shareRevision = shareUrl.searchParams.get('kakao') || '';
  const safeRevision = /^[a-zA-Z0-9_-]{1,100}$/.test(shareRevision) ? shareRevision : '';
  const imageVersion = safeRevision || ('daily-' + kstDate());
  imageUrl = `${BASE}inventory/kakao-daily/latest.jpg?revision=${encodeURIComponent(imageVersion)}`;

  if (imageUrl) {
    const escaped = imageUrl.replace(/&/g, '&amp;').replace(/"/g, '&quot;');
    const tag = `<meta property="og:image" content="${escaped}">`;
    if (/<meta\s+[^>]*property=["']og:image["'][^>]*>/i.test(html)) {
      html = html.replace(/<meta\s+[^>]*property=["']og:image["'][^>]*>/i, tag);
    } else {
      html = html.replace(/<\/head>/i, `${tag}\n</head>`);
    }
    const twitterTag = `<meta name="twitter:image" content="${escaped}">`;
    if (/<meta\s+[^>]*name=["']twitter:image["'][^>]*>/i.test(html)) {
      html = html.replace(/<meta\s+[^>]*name=["']twitter:image["'][^>]*>/i, twitterTag);
    } else {
      html = html.replace(/<\/head>/i, `${twitterTag}\n</head>`);
    }
  }
  const headers = new Headers(response.headers);
  headers.delete('content-length');
  headers.set('cache-control', 'no-store, max-age=0');
  return new Response(html, { status: response.status, headers });
};

export const config = { path: '/' };
